use super::super::{Program, scale_axis};
use destack_vm::Value;

declare_program! {
    /// Rolling hash over a generated byte stream.
    pub const ROLLING_HASH,
    name: "rolling_hash",
    source: include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/mirbench/arithmetic/rolling_hash.mir")),
    entry: "rolling_hash",
    expected: || rolling_hash(10_000),
    default_args: |_interp| vec![Value::int64(10_000)],
    tags: &["arithmetic", "hash"],
    scales: &[
        scale_axis("len", 0, 10000, 100000, 1000000, true),
    ],
}

/// Compute the expected value for the rolling hash benchmark.
fn rolling_hash(length: i64) -> Value {
    // init ring buffer
    let mut buffer = [0i64; 8];
    let mut head = 0usize;

    // init state
    let mut index = 0i64;
    let mut acc1 = 0i64;
    let mut acc2 = 0i64;

    // run hash loop
    while index < length {
        let value = index.wrapping_mul(1103515245).wrapping_add(12345) & 255;

        let old = buffer[head];
        buffer[head] = value;
        head = (head + 1) & 7;

        acc1 = acc1.wrapping_add(value).wrapping_sub(old);
        acc2 = acc2
            .wrapping_mul(16777619)
            .wrapping_add(value ^ (acc1 & 255));
        if (index & 7) == 0 {
            acc2 ^= acc1;
        }

        index = index.wrapping_add(1);
    }

    Value::int64(acc1 ^ acc2)
}
